#!/usr/bin/env bash
# shellcheck disable=SC1087 # faux positif dans la bibliothèque du modèle : "$e[" ($e = \002) n'est pas un tableau
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────


# Usage : scripts/deploy/setup-wizard.sh
# Mise en place de la démo sur Cloud Run (spec #63) : ce que seul Michael peut faire (comptes,
# facturation, valeurs des secrets), puis infra.sh. Relançable : chaque étape déjà faite se garde.

# ── Aides propres à cet assistant ─────────────────────────────────────────
# Aucune valeur secrète n'est affichée ni écrite dans un fichier : lue masquée au clavier, passée à
# gcloud (ou gh) par l'entrée standard, puis oubliée.

done_() { printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"; }

# gcloud refuse de démarrer sous Python 3.9 (celui de macOS).
gcloud_ok() { gcloud --version >/dev/null 2>&1; }

find_python() {
  local v p
  for v in 3.14 3.13 3.12 3.11 3.10; do
    p="$(brew --prefix "python@$v" 2>/dev/null)/bin/python$v"
    if [[ -x "$p" ]]; then printf '%s' "$p"; return 0; fi
  done
  return 1
}

secret_has_value() {
  [[ -n "$(gcloud secrets versions list "$1" --filter='state=ENABLED' --limit=1 --format='value(name)' 2>/dev/null)" ]]
}

# should_set NAME : faut-il demander une valeur ? Non si le secret en a déjà une et qu'on la garde.
should_set() {
  if secret_has_value "$1"; then
    note "$1 a déjà une valeur dans Secret Manager."
    if ! confirm "La remplacer ?"; then done_ "$1 gardé"; return 1; fi
  fi
  return 0
}

# put_secret NAME VALUE : ajoute une version au secret, valeur passée par l'entrée standard.
put_secret() {
  if [[ -z "$2" ]]; then
    warn "valeur vide : $1 non posé"
    SKIPPED+=("secret $1 (relancer l'assistant)")
    return 0
  fi
  printf '%s' "$2" | gcloud secrets versions add "$1" --data-file=- >/dev/null
  done_ "$1 posé dans Secret Manager"
}

# env_value FILE KEY : valeur de KEY dans un fichier KEY=valeur (guillemets retirés), sans l'afficher.
env_value() {
  local line
  line="$(grep -E "^$2=" "$1" 2>/dev/null | tail -n1)" || return 1
  line="${line#*=}"; line="${line#[\"\']}"; line="${line%[\"\']}"
  printf '%s' "$line"
}

# parse_neon URL : découpe la chaîne de connexion Neon en NEON_JDBC, NEON_USER, NEON_PASSWORD.
parse_neon() {
  local re='^postgres(ql)?://([^:/@]+):([^@]+)@([^/?]+)/([^?]+)'
  if ! [[ "$1" =~ $re ]]; then
    warn "format inattendu, attendu : postgresql://utilisateur:mot-de-passe@hôte/base?sslmode=require"
    return 1
  fi
  NEON_USER="${BASH_REMATCH[2]}"; NEON_PASSWORD="${BASH_REMATCH[3]}"
  NEON_HOST="${BASH_REMATCH[4]}"; NEON_DB="${BASH_REMATCH[5]}"
  if [[ "$NEON_HOST" == *-pooler* ]]; then
    warn "hôte $NEON_HOST : c'est le pooler ; il faut la connexion directe (Connection pooling désactivé)"
    return 1
  fi
  if [[ "$NEON_USER$NEON_PASSWORD" == *%* ]]; then
    warn "identifiant ou mot de passe encodé (%) : à poser à la main, décodé"
    return 1
  fi
  NEON_JDBC="jdbc:postgresql://$NEON_HOST/$NEON_DB?sslmode=require"
}

# kafka_pair SERVICE PREFIXE : pose PREFIXE_KAFKA_API_KEY et PREFIXE_KAFKA_API_SECRET.
# Avec reuse=1, les reprend de .secrets/confluent.env (clés créées pour #55).
kafka_pair() {
  local service="$1" prefix="$2" part name value
  for part in KEY SECRET; do
    name="${prefix}_KAFKA_API_${part}"
    should_set "$name" || continue
    value=""
    if (( reuse )); then value="$(env_value "$confluent_env" "$name" || true)"; fi
    if [[ -z "$value" ]]; then
      if [[ "$part" == KEY ]]; then
        step "Clé de $service : cluster → API Keys → Add key → Granular access → compte de service $service"
        step "(le créer s'il manque) → droits du README (« Contre Confluent Cloud ») → copier la clé et le secret."
      fi
      ask_secret value "$name (masqué) :"
    fi
    put_secret "$name" "$value"
  done
}

run_wizard() {

TOTAL_STAGES=11

root="$(cd "$(dirname "$0")/../.." && pwd)"
cd "$root"
# shellcheck source-path=SCRIPTDIR source=names.sh
source "$root/scripts/deploy/names.sh"
# Valeurs non secrètes gardées pour une relance (dossier ignoré par git). Jamais de secret dedans.
mkdir -p "$root/.secrets"
ENV_FILE="$root/.secrets/deploy.env"
confluent_env="$root/.secrets/confluent.env"

banner "Mise en place de la démo sur Cloud Run"

# ──────────────────────────────────────────────────────────────────────────
stage "gcloud en local (Python 3.10 à 3.14)"
if gcloud_ok; then
  done_ "gcloud démarre"
else
  say "gcloud refuse le Python 3.9 de macOS. Il lui faut Python 3.10 à 3.14, désigné par CLOUDSDK_PYTHON."
  py="$(find_python || true)"
  if [[ -z "$py" ]]; then
    confirm "Installer python@3.13 avec Homebrew ?" || { warn "gcloud est indispensable pour la suite."; exit 1; }
    brew install python@3.13
    py="$(find_python)"
  fi
  export CLOUDSDK_PYTHON="$py"
  gcloud_ok || { warn "gcloud ne démarre toujours pas avec $py."; exit 1; }
  done_ "gcloud démarre avec $py"
  line="export CLOUDSDK_PYTHON=\"$py\""
  if grep -qF "$line" "$HOME/.zshrc" 2>/dev/null; then
    done_ "déjà dans ~/.zshrc"
  elif confirm "Ajouter « $line » à ~/.zshrc, pour gcloud hors de l'assistant ?"; then
    printf '\n# gcloud refuse le Python 3.9 de macOS\n%s\n' "$line" >> "$HOME/.zshrc"
    done_ "ajouté à ~/.zshrc (nouveaux terminaux)"
  else
    note "Hors de l'assistant, lancer d'abord : $line"
  fi
fi
pause "Entrée pour continuer"

# ──────────────────────────────────────────────────────────────────────────
stage "Connexions : gcloud et GitHub"
account="$(gcloud auth list --filter=status:ACTIVE --format='value(account)' 2>/dev/null | head -n1)"
if [[ -n "$account" ]]; then
  done_ "gcloud connecté : $account"
else
  say "gcloud ouvre le navigateur : se connecter avec le compte Google du projet."
  pause "Entrée pour lancer gcloud auth login"
  gcloud auth login
fi
if gh auth status >/dev/null 2>&1; then
  done_ "gh connecté"
else
  say "gh pose les variables du dépôt GitHub (dernière étape)."
  pause "Entrée pour lancer gh auth login"
  gh auth login
fi
pause "Entrée pour continuer"

# ──────────────────────────────────────────────────────────────────────────
stage "Projet GCP et facturation"
say "Un projet dédié à la démo, rattaché à un compte de facturation (Cloud Run l'exige, même gratuit)."
ask GCP_PROJECT_ID "Identifiant du projet, existant ou à créer (ex. logistics-demo-4821) :"
if ! gcloud projects describe "$GCP_PROJECT_ID" >/dev/null 2>&1; then
  confirm "Le projet $GCP_PROJECT_ID n'existe pas (ou est inaccessible). Le créer ?" \
    || { warn "Créer le projet puis relancer l'assistant."; exit 1; }
  gcloud projects create "$GCP_PROJECT_ID" --name="Logistics demo"
fi
write_env GCP_PROJECT_ID "$GCP_PROJECT_ID"
write_env GCP_PROJECT_NUMBER "$(gcloud projects describe "$GCP_PROJECT_ID" --format='value(projectNumber)')"
export CLOUDSDK_CORE_PROJECT="$GCP_PROJECT_ID"
open_url "https://console.cloud.google.com/billing/linkedaccount?project=$GCP_PROJECT_ID"
step "Si le projet n'a pas de compte de facturation : Link a billing account → choisir le compte → Set account."
step "Sans compte de facturation : Manage billing accounts → Create account, puis revenir à cette page."
pause "Entrée une fois la facturation rattachée"
if [[ "$(gcloud billing projects describe "$GCP_PROJECT_ID" --format='value(billingEnabled)' 2>/dev/null || true)" == True ]]; then
  done_ "facturation active"
else
  warn "facturation non vérifiée : sans elle, infra.sh échouera à activer les API."
fi
pause "Entrée pour continuer"

# ──────────────────────────────────────────────────────────────────────────
stage "Alerte de budget : 20 \$ par mois"
open_url "https://console.cloud.google.com/billing/budgets?project=$GCP_PROJECT_ID"
step "Create budget → Name : logistics-demo."
step "Scope → Projects : seulement $GCP_PROJECT_ID → Next."
step "Amount → Specified amount, Target amount : 20 (devise du compte de facturation) → Next."
step "Actions : seuils 50 %, 90 %, 100 % (Actual), « Email alerts to billing admins and users » coché → Finish."
note "L'alerte prévient, elle n'arrête rien : seul le workflow down arrête la démo."
pause "Entrée une fois le budget créé"

# ──────────────────────────────────────────────────────────────────────────
stage "Ressources GCP (infra.sh)"
say "API, dépôt d'images, comptes de service et droits, conteneurs de secrets (vides),"
say "fédération d'identité pour GitHub Actions, métrique de coût d'ai-service."
note "Idempotent : sans risque à relancer, ne supprime rien."
if confirm "Lancer scripts/deploy/infra.sh sur $GCP_PROJECT_ID ($REGION) ?"; then
  PROJECT_ID="$GCP_PROJECT_ID" REGION="$REGION" "$root/scripts/deploy/infra.sh"
else
  warn "Les étapes suivantes supposent qu'infra.sh a déjà tourné (conteneurs de secrets)."
fi
pause "Entrée pour continuer"

# ──────────────────────────────────────────────────────────────────────────
stage "Base Neon (PostgreSQL 17)"
if secret_has_value DB_URL && secret_has_value DB_USER && secret_has_value DB_PASSWORD \
    && ! confirm "DB_URL, DB_USER et DB_PASSWORD ont déjà une valeur. Les remplacer ?"; then
  done_ "base gardée"
else
  open_url "https://console.neon.tech/"
  step "Créer un compte (offre Free), puis un projet : nom logistics-demo, Postgres 17, région AWS Europe Central 1 (Frankfurt)."
  step "Tableau de bord du projet → Connect → désactiver « Connection pooling » : l'hôte ne doit pas contenir -pooler"
  step "(Flyway et ses verrous veulent une connexion directe)."
  step "Copier la chaîne de connexion : postgresql://utilisateur:mot-de-passe@ep-….neon.tech/neondb?sslmode=require…"
  ask_secret NEON_URL "Coller la chaîne de connexion (masquée) :"
  if parse_neon "$NEON_URL"; then
    note "hôte $NEON_HOST, base $NEON_DB"
    put_secret DB_URL "$NEON_JDBC"
    put_secret DB_USER "$NEON_USER"
    put_secret DB_PASSWORD "$NEON_PASSWORD"
  else
    SKIPPED+=("secrets DB_URL, DB_USER, DB_PASSWORD (relancer l'assistant)")
  fi
  unset NEON_URL NEON_JDBC NEON_USER NEON_PASSWORD
fi
pause "Entrée pour continuer"

# ──────────────────────────────────────────────────────────────────────────
stage "Clé de signature des JWT"
say "Une clé RSA neuve, distincte de la clé locale (.secrets/jwt-private-key.pem) :"
say "un jeton émis en local n'est pas valable en ligne. Elle va droit dans Secret Manager."
if should_set JWT_PRIVATE_KEY; then
  JWT_KEY="$("$root/scripts/generate-jwt-key.sh" --stdout)"
  if [[ "$JWT_KEY" == "-----BEGIN PRIVATE KEY-----"* ]]; then
    put_secret JWT_PRIVATE_KEY "$JWT_KEY"
    note "La remplacer plus tard invalide les jetons déjà émis (il suffit de se reconnecter)."
  else
    warn "openssl n'a pas produit de clé PKCS#8 : JWT_PRIVATE_KEY non posé."
    SKIPPED+=("secret JWT_PRIVATE_KEY")
  fi
  unset JWT_KEY
fi
pause "Entrée pour continuer"

# ──────────────────────────────────────────────────────────────────────────
stage "Premier ADMIN"
say "shipment-service crée cet ADMIN au démarrage s'il n'en existe aucun ;"
say "le parcours de fumée du workflow up se connecte avec lui."
ask BOOTSTRAP_ADMIN_USERNAME "Identifiant de l'ADMIN (ex. admin) :"
write_env BOOTSTRAP_ADMIN_USERNAME "$BOOTSTRAP_ADMIN_USERNAME"
if should_set BOOTSTRAP_ADMIN_PASSWORD; then
  while :; do
    ask_secret ADMIN_PASSWORD "Mot de passe, 12 caractères au moins (masqué) :"
    ask_secret ADMIN_PASSWORD_AGAIN "Le retaper :"
    if (( ${#ADMIN_PASSWORD} < 12 )); then warn "moins de 12 caractères : shipment-service refuserait de démarrer."
    elif [[ "$ADMIN_PASSWORD" != "$ADMIN_PASSWORD_AGAIN" ]]; then warn "les deux saisies diffèrent."
    else break; fi
  done
  put_secret BOOTSTRAP_ADMIN_PASSWORD "$ADMIN_PASSWORD"
  set_secret BOOTSTRAP_ADMIN_PASSWORD "$ADMIN_PASSWORD"   # secret GitHub, pour la fumée
  unset ADMIN_PASSWORD ADMIN_PASSWORD_AGAIN
else
  note "Le secret GitHub BOOTSTRAP_ADMIN_PASSWORD doit porter la même valeur (gh secret set BOOTSTRAP_ADMIN_PASSWORD)."
fi
note "Une fois l'ADMIN créé en base, changer ce secret ne change plus son mot de passe."
pause "Entrée pour continuer"

# ──────────────────────────────────────────────────────────────────────────
stage "Confluent Cloud : adresse et clés d'API"
say "Une clé d'API par service, shipment-service et ingestion-service (droits : README, « Contre Confluent Cloud »)."
open_url "https://confluent.cloud/environments"
step "Cluster → Cluster settings → Endpoints : copier le Bootstrap server (pkc-….confluent.cloud:9092), pas l'endpoint REST."
if [[ -f "$confluent_env" ]]; then
  note "Celui de .secrets/confluent.env : $(env_value "$confluent_env" CONFLUENT_BOOTSTRAP_SERVERS || true)"
fi
while :; do
  ask KAFKA_BOOTSTRAP_SERVERS "Bootstrap server :"
  if [[ "$KAFKA_BOOTSTRAP_SERVERS" == *:9092 && "$KAFKA_BOOTSTRAP_SERVERS" != http* ]]; then break; fi
  warn "attendu : pkc-….confluent.cloud:9092 (l'endpoint REST https://…:443 coupe la connexion)."
done
write_env KAFKA_BOOTSTRAP_SERVERS "$KAFKA_BOOTSTRAP_SERVERS"
reuse=0
if [[ -f "$confluent_env" ]] && confirm "Reprendre les clés d'API de .secrets/confluent.env (créées pour #55) ?"; then
  reuse=1
fi
kafka_pair shipment-service SHIPMENT
kafka_pair ingestion-service INGESTION
pause "Entrée pour continuer"

# ──────────────────────────────────────────────────────────────────────────
stage "Clé de l'API Claude (ai-service)"
warn "Chaque extraction est facturée. ai-service s'arrête à 1 \$ par jour ; la Console Anthropic porte en plus un plafond mensuel."
if should_set ANTHROPIC_API_KEY; then
  open_url "https://console.anthropic.com/settings/keys"
  step "Create Key → nom logistics-cloud-run → copier la clé (sk-ant-…, affichée une seule fois)."
  ask_secret CLAUDE_KEY "Clé d'API (masquée) :"
  put_secret ANTHROPIC_API_KEY "$CLAUDE_KEY"
  unset CLAUDE_KEY
fi
open_url "https://console.anthropic.com/settings/limits"
step "Vérifier le plafond de dépense mensuel de l'organisation (spend limit), le baisser si besoin."
pause "Entrée une fois le plafond vérifié"

# ──────────────────────────────────────────────────────────────────────────
stage "Variables du dépôt GitHub"
say "Lues par les workflows up et down. Aucune n'est secrète."
set_var GCP_PROJECT_ID "$GCP_PROJECT_ID"
